/* iOS Google sign-in (engine/platform/google_auth.h).
 *
 * Same flow the GoogleSignIn SDK runs, without the Swift package (the Xcode
 * project is generated by CMake): the system sign-in sheet
 * (ASWebAuthenticationSession) with the iOS OAuth client, PKCE and a nonce,
 * then the code -> token exchange with Google. The ID token's `nonce` claim
 * is sha256(raw nonce), so Supabase can verify it and "Skip nonce check"
 * stays off. Compiled with ARC. */
#import <AuthenticationServices/AuthenticationServices.h>
#import <CommonCrypto/CommonDigest.h>
#import <Security/Security.h>
#import <UIKit/UIKit.h>

#include <SDL3/SDL.h>

#include "platform/google_auth_internal.h"

@interface MGGoogleSignIn : NSObject <ASWebAuthenticationPresentationContextProviding>
@property(nonatomic, weak) UIWindow *window;
@property(nonatomic, strong) ASWebAuthenticationSession *session;
@end

@implementation MGGoogleSignIn
- (ASPresentationAnchor)presentationAnchorForWebAuthenticationSession:(ASWebAuthenticationSession *)session
{
    (void)session;
    return self.window;
}
@end

static NSString *b64url(NSData *d)
{
    NSString *s = [d base64EncodedStringWithOptions:0];
    s = [s stringByReplacingOccurrencesOfString:@"+" withString:@"-"];
    s = [s stringByReplacingOccurrencesOfString:@"/" withString:@"_"];
    return [s stringByReplacingOccurrencesOfString:@"=" withString:@""];
}

static NSData *sha256(NSString *s)
{
    NSData *in = [s dataUsingEncoding:NSUTF8StringEncoding];
    unsigned char out[CC_SHA256_DIGEST_LENGTH];
    CC_SHA256(in.bytes, (CC_LONG)in.length, out);
    return [NSData dataWithBytes:out length:sizeof(out)];
}

static NSString *hex(NSData *d)
{
    NSMutableString *s = [NSMutableString stringWithCapacity:d.length * 2];
    const unsigned char *b = d.bytes;
    for (NSUInteger i = 0; i < d.length; i++) {
        [s appendFormat:@"%02x", b[i]];
    }
    return s;
}

static NSString *random_token(size_t bytes)
{
    NSMutableData *d = [NSMutableData dataWithLength:bytes];
    if (SecRandomCopyBytes(kSecRandomDefault, bytes, d.mutableBytes) != errSecSuccess) {
        arc4random_buf(d.mutableBytes, bytes);
    }
    return b64url(d);
}

static NSString *query_value(NSURL *url, NSString *name)
{
    for (NSURLQueryItem *q in [NSURLComponents componentsWithURL:url resolvingAgainstBaseURL:NO].queryItems) {
        if ([q.name isEqualToString:name]) {
            return q.value;
        }
    }
    return nil;
}

static NSString *form_escape(NSString *s)
{
    NSMutableCharacterSet *ok = [[NSCharacterSet alphanumericCharacterSet] mutableCopy];
    [ok addCharactersInString:@"-._~"];
    return [s stringByAddingPercentEncodingWithAllowedCharacters:ok];
}

static void finish(GoogleAuth *g, NSString *token, NSString *nonce, NSString *error)
{
    google_auth_finish(g, token ? token.UTF8String : NULL, nonce ? nonce.UTF8String : NULL,
                       error ? error.UTF8String : NULL);
    if (g->platform) {
        CFBridgingRelease(g->platform); /* drops the session + presenter */
        g->platform = NULL;
    }
}

/* code -> id_token (public client: PKCE verifier instead of a secret) */
static void exchange(GoogleAuth *g, NSString *code, NSString *client, NSString *redirect, NSString *verifier,
                     NSString *raw_nonce)
{
    NSMutableURLRequest *req =
        [NSMutableURLRequest requestWithURL:[NSURL URLWithString:@"https://oauth2.googleapis.com/token"]];
    req.HTTPMethod = @"POST";
    [req setValue:@"application/x-www-form-urlencoded" forHTTPHeaderField:@"Content-Type"];
    NSString *body = [NSString stringWithFormat:@"grant_type=authorization_code&code=%@&client_id=%@&redirect_uri=%@"
                                                @"&code_verifier=%@",
                                                form_escape(code), form_escape(client), form_escape(redirect),
                                                form_escape(verifier)];
    req.HTTPBody = [body dataUsingEncoding:NSUTF8StringEncoding];
    [[[NSURLSession sharedSession]
        dataTaskWithRequest:req
          completionHandler:^(NSData *data, NSURLResponse *resp, NSError *err) {
            (void)resp;
            NSDictionary *json = data ? [NSJSONSerialization JSONObjectWithData:data options:0 error:nil] : nil;
            NSString *idt = [json isKindOfClass:[NSDictionary class]] ? json[@"id_token"] : nil;
            if ([idt isKindOfClass:[NSString class]] && idt.length > 0) {
                finish(g, idt, raw_nonce, nil);
            } else {
                NSString *why = err ? err.localizedDescription
                                    : ([json isKindOfClass:[NSDictionary class]] && json[@"error"]
                                           ? [NSString stringWithFormat:@"token exchange: %@", json[@"error"]]
                                           : @"token exchange failed");
                finish(g, nil, nil, why);
            }
        }] resume];
}

bool google_auth_platform_available(const GoogleAuth *g) { return g->ios_client_id[0] != 0; }

bool google_auth_platform_start(GoogleAuth *g, struct SDL_Window *window)
{
    UIWindow *win = (__bridge UIWindow *)SDL_GetPointerProperty(SDL_GetWindowProperties(window),
                                                                 SDL_PROP_WINDOW_UIKIT_WINDOW_POINTER, NULL);
    NSString *client = @(g->ios_client_id); /* "<id>.apps.googleusercontent.com" */
    NSString *id_part = [client stringByReplacingOccurrencesOfString:@".apps.googleusercontent.com" withString:@""];
    NSString *scheme = [@"com.googleusercontent.apps." stringByAppendingString:id_part];
    NSString *redirect = [scheme stringByAppendingString:@":/oauth2redirect"];
    NSString *verifier = random_token(32);
    NSString *raw_nonce = random_token(24);
    NSString *state = random_token(16);

    NSURLComponents *c = [NSURLComponents componentsWithString:@"https://accounts.google.com/o/oauth2/v2/auth"];
    c.queryItems = @[
        [NSURLQueryItem queryItemWithName:@"client_id" value:client],
        [NSURLQueryItem queryItemWithName:@"redirect_uri" value:redirect],
        [NSURLQueryItem queryItemWithName:@"response_type" value:@"code"],
        [NSURLQueryItem queryItemWithName:@"scope" value:@"openid email profile"],
        [NSURLQueryItem queryItemWithName:@"code_challenge" value:b64url(sha256(verifier))],
        [NSURLQueryItem queryItemWithName:@"code_challenge_method" value:@"S256"],
        [NSURLQueryItem queryItemWithName:@"nonce" value:hex(sha256(raw_nonce))],
        [NSURLQueryItem queryItemWithName:@"state" value:state],
        [NSURLQueryItem queryItemWithName:@"prompt" value:@"select_account"],
    ];
    MGGoogleSignIn *flow = [MGGoogleSignIn new];
    flow.window = win;
    flow.session = [[ASWebAuthenticationSession alloc]
              initWithURL:c.URL
        callbackURLScheme:scheme
        completionHandler:^(NSURL *callback, NSError *error) {
            if (error || !callback) {
                BOOL cancelled = error.code == ASWebAuthenticationSessionErrorCodeCanceledLogin;
                finish(g, nil, nil, cancelled ? @"cancelled" : error.localizedDescription);
                return;
            }
            NSString *code = query_value(callback, @"code");
            if (!code || ![query_value(callback, @"state") isEqualToString:state]) {
                NSString *e = query_value(callback, @"error");
                finish(g, nil, nil, e ? e : @"no authorization code");
                return;
            }
            exchange(g, code, client, redirect, verifier, raw_nonce);
        }];
    flow.session.presentationContextProvider = flow;
    flow.session.prefersEphemeralWebBrowserSession = NO;
    g->platform = (void *)CFBridgingRetain(flow); /* alive until finish() */
    if (![flow.session start]) {
        CFBridgingRelease(g->platform);
        g->platform = NULL;
        return false;
    }
    return true;
}
